Item.method_code:
// 呼び出し元のカンマ区切り文字列を分割して配列化
var args = arguments[1].split(',');

// メッセージを取得
var userMsgItem = aras.IomInnovator.newItem("UserMessage", "get");
userMsgItem.setAttribute("select", "text");
userMsgItem.setProperty("name", args[0]);
userMsgItem = userMsgItem.apply();

// UserMessageが1件のみヒットした場合のみtext取得
var msg = "";
if (userMsgItem.getItemCount && userMsgItem.getItemCount() === 1) {
    msg = userMsgItem.getProperty("text", "");
}

// 第2引数以降（args[1], args[2], ...）で{0}, {1}, ...を順に置換
for (var i = 1; i < args.length; i++) {
    var repStr = '{' + String(i - 1) + '}';
    msg = msg.replaceAll(repStr, args[i]);　//全置換する
}

return msg;
